<http://www.example.org/ontology/EDIFACTScenario> a owl:Ontology ;
    rdfs:label "EDIFACT Scenario Ontology" ;
    rdfs:comment "An ontology modeling EDIFACT invoices, organizations, roles, items, and business processes." .

:EDIFACTMessage a owl:Class ;
    rdfs:label "EDIFACT Message" ;
    rdfs:comment "An EDIFACT message containing one or more invoices." .

:Invoice a owl:Class ;
    rdfs:label "Invoice" ;
    rdfs:comment "An invoice as listed in an EDIFACT message." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "An organization involved in an invoice, acting as buyer, seller, etc." .

:Role a owl:Class ;
    rdfs:label "Role" ;
    rdfs:comment "A role played by an organization in the context of an invoice (e.g., buyer, seller)." .

:BuyerRole a owl:Class ;
    rdfs:label "Buyer Role" ;
    rdfs:comment "The role of a buyer in an invoice." ;
    rdfs:subClassOf :Role .

:SellerRole a owl:Class ;
    rdfs:label "Seller Role" ;
    rdfs:comment "The role of a seller in an invoice." ;
    rdfs:subClassOf :Role .

:BuyerRole owl:disjointWith :SellerRole .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal address for an organization." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "An item sold in an invoice." .

:InvoiceDetail a owl:Class ;
    rdfs:label "Invoice Detail" ;
    rdfs:comment "Details about an invoice, such as invoice number and amount." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which an invoice can be assigned." .

:InvoiceItemAssignment a owl:Class ;
    rdfs:label "Invoice Item Assignment" ;
    rdfs:comment "Reifies the assignment of an item to an invoice, including net price." .

:hasInvoice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :EDIFACTMessage ;
    rdfs:range :Invoice ;
    rdfs:label "has invoice" ;
    rdfs:comment "Relates an EDIFACT message to an invoice it contains." ;
    owl:inverseOf :isInvoiceOf .

:isInvoiceOf a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :EDIFACTMessage ;
    rdfs:label "is invoice of" ;
    rdfs:comment "Inverse property of hasInvoice." ;
    owl:inverseOf :hasInvoice .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :Organization ;
    rdfs:label "involves organization" ;
    rdfs:comment "Indicates an organization involved in an invoice." ;
    owl:inverseOf :isOrganizationInvolvedIn .

:isOrganizationInvolvedIn a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Invoice ;
    rdfs:label "is organization involved in" ;
    rdfs:comment "Inverse property of involvesOrganization." ;
    owl:inverseOf :involvesOrganization .

:hasRole a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Role ;
    rdfs:label "has role" ;
    rdfs:comment "Relates an organization to a role it plays." ;
    owl:inverseOf :isRoleOf .

:isRoleOf a owl:ObjectProperty ;
    rdfs:domain :Role ;
    rdfs:range :Organization ;
    rdfs:label "is role of" ;
    rdfs:comment "Inverse property of hasRole." ;
    owl:inverseOf :hasRole .

:playsRoleInInvoice a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Invoice ;
    rdfs:label "plays role in invoice" ;
    rdfs:comment "Relates an organization to an invoice where it plays a role." ;
    owl:inverseOf :hasRolePlayer .

:hasRolePlayer a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :Organization ;
    rdfs:label "has role player" ;
    rdfs:comment "Inverse property of playsRoleInInvoice." ;
    owl:inverseOf :playsRoleInInvoice .

:hasAddress a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has address" ;
    rdfs:comment "Relates an organization to its address." ;
    owl:inverseOf :isAddressOf .

:isAddressOf a owl:ObjectProperty ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    rdfs:label "is address of" ;
    rdfs:comment "Inverse property of hasAddress." ;
    owl:inverseOf :hasAddress .

:hasItemAssignment a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :InvoiceItemAssignment ;
    rdfs:label "has item assignment" ;
    rdfs:comment "Relates an invoice to an item assignment (reification)." ;
    owl:inverseOf :isItemAssignmentOf .

:isItemAssignmentOf a owl:ObjectProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range :Invoice ;
    rdfs:label "is item assignment of" ;
    rdfs:comment "Inverse property of hasItemAssignment." ;
    owl:inverseOf :hasItemAssignment .

:assignedItem a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range :Item ;
    rdfs:label "assigned item" ;
    rdfs:comment "Relates an item assignment to the assigned item." ;
    owl:inverseOf :isAssignedTo .

:isAssignedTo a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :InvoiceItemAssignment ;
    rdfs:label "is assigned to" ;
    rdfs:comment "Inverse property of assignedItem." ;
    owl:inverseOf :assignedItem .

:netPrice a owl:DatatypeProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range xsd:decimal ;
    rdfs:label "net price" ;
    rdfs:comment "The net price of an item in an invoice." .

:hasInvoiceDetail a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :InvoiceDetail ;
    rdfs:label "has invoice detail" ;
    rdfs:comment "Relates an invoice to its details." ;
    owl:inverseOf :isInvoiceDetailOf .

:isInvoiceDetailOf a owl:ObjectProperty ;
    rdfs:domain :InvoiceDetail ;
    rdfs:range :Invoice ;
    rdfs:label "is invoice detail of" ;
    rdfs:comment "Inverse property of hasInvoiceDetail." ;
    owl:inverseOf :hasInvoiceDetail .

:invoiceAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceDetail ;
    rdfs:range xsd:decimal ;
    rdfs:label "invoice amount" ;
    rdfs:comment "The total amount of the invoice." .

:invoiceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceDetail ;
    rdfs:range xsd:string ;
    rdfs:label "invoice number" ;
    rdfs:comment "The invoice number." .

:partOfBusinessProcess a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :BusinessProcess ;
    rdfs:label "part of business process" ;
    rdfs:comment "Assigns an invoice to a business process." ;
    owl:inverseOf :hasInvoice .

:buyer a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :Organization ;
    rdfs:label "buyer" ;
    rdfs:comment "The buyer organization in the invoice." ;
    owl:inverseOf :isBuyerOf .

:isBuyerOf a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Invoice ;
    rdfs:label "is buyer of" ;
    rdfs:comment "Inverse property of buyer." ;
    owl:inverseOf :buyer .

:seller a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :Organization ;
    rdfs:label "seller" ;
    rdfs:comment "The seller organization in the invoice." ;
    owl:inverseOf :isSellerOf .

:isSellerOf a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Invoice ;
    rdfs:label "is seller of" ;
    rdfs:comment "Inverse property of seller." ;
    owl:inverseOf :seller .

:organizationName a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string ;
    rdfs:label "organization name" ;
    rdfs:comment "The name of the organization." .

:addressLine a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "address line" ;
    rdfs:comment "The address line of the address." .

:itemDescription a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Item ;
    rdfs:range xsd:string ;
    rdfs:label "item description" ;
    rdfs:comment "A description of the item sold." .

